/** Coordinate unit for a {@link CropRect}. `'%'` is relative to the displayed image and survives container resize; `'px'` is display pixels. */
export type CropUnit = 'px' | '%';
/**
 * A crop selection rectangle. `x`/`y` are the top-left corner. When `x`/`y` are omitted the
 * selection is centered. `unit` defaults to `'%'` (resize-stable); set `'px'` to work in
 * display pixels.
 */
export interface CropRect {
    x?: number;
    y?: number;
    width: number;
    height: number;
    unit?: CropUnit;
}
/**
 * A fully-resolved crop rectangle with concrete coordinates, as returned by `getCropRect()`
 * (scaled to the image's natural pixels).
 */
export interface CropRectPixels {
    x: number;
    y: number;
    width: number;
    height: number;
    unit: 'px';
}
/** Aspect ratio of the crop selection. `'custom'` allows freeform resizing. */
export type CropRatio = 'custom' | '1:1' | '16:9' | '9:16';
/** Visual shape of the crop selection. `'circle'` forces a 1:1 ratio. */
export type CropShape = 'rect' | 'circle';
/** MIME type of the image produced by `screenshot()`. */
export type ImageType = 'image/png' | 'image/jpeg' | 'image/webp';
/** Options for `screenshot()`. */
export interface CropScreenshotOptions {
    /** Output MIME type. Defaults to `'image/jpeg'`. */
    type?: ImageType;
    /** Output quality `0`–`1`, applied to `'image/jpeg'` and `'image/webp'`. Defaults to `0.9`. */
    quality?: number;
}
/** Which handle (or `'move'`) a pointer gesture is acting on. */
export type CropDragType = 'top' | 'bottom' | 'left' | 'right' | 'topLeft' | 'topRight' | 'bottomLeft' | 'bottomRight' | 'move';
